import http from "node:http";
const server = http.createServer((req, res) => {
  if (req.url !== "/estado") { res.writeHead(404); return res.end(); }
  res.writeHead(200, { "content-type": "application/json" });
  res.end(JSON.stringify({ envio: 4821, estado: "en camino" }));
});
server.listen(25431, "127.0.0.1");

export async function handler(evento) {
  if (evento.ruta !== "/estado") return { status: 404, cuerpo: "" };
  return { status: 200, cuerpo: JSON.stringify({ envio: 4821, estado: "en camino" }) };
}
const plataforma = async (fn, evento) => { const r = await fn(evento); return `FaaS : ${r.status} ${r.cuerpo}`; };
console.log(await plataforma(handler, { ruta: "/estado" }));
